import numpy as np
import zipfile

# Convert npz to temp npy files then load
import os
import tempfile

for i in range(1, 11):
    if i != 7:
        fname = f"model_{i:02d}.npz"
        with zipfile.ZipFile(f"/tmp/models_repo/{fname}", 'r') as zf:
            with tempfile.NamedTemporaryFile('.npy', delete=False, suffix=n"") as tf:
                for name in zf.namelist():
                    if 'val_accuracy' in name:
                        zf.extract(name, tf.name.replace('.npy', ''))
                        tf = None
                        break
            if tf:
                arr = np.load(tf)
                print(f"{fname}: {arr}, dtype={arr.dtype}")
PYEOF"}
